'use strict';
const $=id=>document.getElementById(id);
const places=[['Production with potential','Northern Brazil and Guyana offer agricultural supply. HarvestLink’s starting point is the farmer’s available crop, quantity, quality and harvest window—not a single demonstration crop.'],['A practical first connection','Bonfim and Lethem provide a focused place to demonstrate bilingual harvest coordination. Compatible lots become a shared proposal, with farmer confirmation and clear costs.'],['Connect supply to routes','As the corridor develops, coordinated collection, packaging and handover can help connect inland production with coastal trade routes. Logistics and documentary requirements belong in the same workflow.'],['Grow into wider demand','The vision is a network linking local producers with regional and international buyers. Begin with a reliable local transaction, then replicate the coordination model across crops and communities.']];
document.querySelectorAll('[data-place]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-place]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});const [title,copy]=places[Number(b.dataset.place)];$('route-detail').replaceChildren(Object.assign(document.createElement('h3'),{textContent:title}),Object.assign(document.createElement('p'),{textContent:copy}));}));document.querySelector('[data-place="0"]').click();
let lang='en',step=0;
const journey=[{title:'Start with your language.',copy:'Onboarding creates the account in the background. Ask for consent, a preferred name and the producing community; review before saving.',en:[['agent','Welcome to HarvestLink. English or Português?'],['farmer','English. My name is Ana. I grow crops near Boa Vista.'],['agent','I’ll help organise harvests and compare opportunities. May I save your profile?']],pt:[['agent','Bem-vinda ao HarvestLink. English ou Português?'],['farmer','Português. Sou Ana e produzo perto de Boa Vista.'],['agent','Vou ajudar a organizar colheitas e comparar oportunidades. Posso salvar seu perfil?']]},{title:'Describe it naturally.',copy:'The farmer gives the information they have. Intent recognition and structured tools turn the message into a draft and ask for missing details.',en:[['farmer','I have 220 kg of cassava ready this week.'],['agent','I’ll prepare a harvest draft. What grade is it, and on which date will it be ready?'],['farmer','Grade A, 4 October 2026.']],pt:[['farmer','Tenho 220 kg de mandioca para esta semana.'],['agent','Vou preparar um rascunho. Qual é a classificação e a data de disponibilidade?'],['farmer','Classe A, 4 de outubro de 2026.']]},{title:'Review. Then confirm.',copy:'The farmer approves the record. A clear crop, quantity, location, quality and date make it useful for matching and buyer summaries.',en:[['agent','Review: cassava · 220 kg · grade A · Boa Vista · 4 October 2026. Confirm or correct?'],['farmer','Confirm.'],['agent','Harvest saved. I can now compare suitable opportunities.']],pt:[['agent','Revise: mandioca · 220 kg · classe A · Boa Vista · 4 de outubro de 2026. Confirmar ou corrigir?'],['farmer','Confirmar.'],['agent','Colheita salva. Agora podemos comparar oportunidades compatíveis.']]},{title:'Pool. Compare. Choose.',copy:'A compatible 80 kg partner lot completes a 300 kg demonstration order. The comparison shows the farmer’s share after costs, rather than just the headline buyer price.',en:[['agent','Demo proposal: your 220 kg + a compatible 80 kg lot meet a 300 kg buyer order. Estimated net: BRL 632 pooled, versus BRL 605 locally. Want the cost breakdown?'],['farmer','Show me the costs before I decide.']],pt:[['agent','Proposta demo: seus 220 kg + 80 kg compatíveis completam um pedido de 300 kg. Líquido estimado: BRL 632 em conjunto ou BRL 605 na venda local. Quer ver os custos?'],['farmer','Mostre os custos antes de eu decidir.']]},{title:'Coordinate the next step.',copy:'An approved choice feeds the control panel and a reviewed handover draft. Cross-border shipment awaits buyer confirmation and trade-requirement checks.',en:[['farmer','Save my preference for the pooled proposal.'],['agent','Preference recorded. The handover draft keeps lot details, costs and the next review together. Shipment awaits buyer confirmation and trade-requirement checks.']],pt:[['farmer','Salve minha preferência pela proposta conjunta.'],['agent','Preferência registrada. O rascunho de entrega reúne lotes, custos e a próxima revisão. O envio aguarda confirmação do comprador e verificação dos requisitos comerciais.']]}];
function renderJourney(){const s=journey[step];$('step-count').textContent=`STEP ${step+1} / ${journey.length}`;$('step-title').textContent=s.title;$('step-copy').textContent=s.copy;$('messages').replaceChildren(...s[lang].map(([who,text])=>Object.assign(document.createElement('p'),{className:`bubble ${who}`,textContent:text})));$('back').disabled=step===0;$('next').textContent=step===4?'Restart journey ↺':'Next step →';$('dots').replaceChildren(...journey.map((_,i)=>{const b=document.createElement('button');b.className=i===step?'active':'';b.setAttribute('aria-label',`Go to step ${i+1}`);b.setAttribute('aria-pressed',String(i===step));b.onclick=()=>{step=i;renderJourney()};return b}));}
$('next').onclick=()=>{step=(step+1)%5;renderJourney()};$('back').onclick=()=>{step=Math.max(0,step-1);renderJourney()};document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;document.querySelectorAll('[data-lang]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderJourney()});renderJourney();
const money=x=>x.toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2});let current;
function calculate(){const kg=Number($('kg').value),fx=Number($('fx').value),freight=Number($('freight').value),gross=300*.95*180/fx,cost=300*(freight+.30+.20)+gross*.02+50,pooled=(gross-cost)*kg/300,local=kg*2.75;current={kg,fx,freight,pooled,local};$('kg-label').textContent=`${kg} kg`;$('fx-label').textContent=`${fx} GYD / BRL`;$('freight-label').textContent=`BRL ${money(freight)} / kg`;$('partner').textContent=`${300-kg} kg`;$('local').textContent=money(local);$('pooled').textContent=money(pooled);$('difference').textContent=`At these assumptions, ${pooled>=local?'pooling':'the local sale'} returns BRL ${money(Math.abs(pooled-local))} more to you.`;$('math').textContent=`Pool gross: 300 × 95% × GYD 180 ÷ ${fx} = BRL ${money(gross)}. Pool costs: BRL ${money(cost)}. Your share: (${money(gross)} − ${money(cost)}) × ${kg}/300 = BRL ${money(pooled)}. Local: ${kg} × (3 − 0.25) = BRL ${money(local)}.`;$('choice').textContent='';}
['kg','fx','freight'].forEach(id=>$(id).addEventListener('input',calculate));calculate();$('confirm').onclick=()=>{try{localStorage.setItem('harvestlink-pitch-preference',JSON.stringify({...current,savedAt:new Date().toISOString()}));$('choice').textContent='Demo preference saved on this device. No sale or shipment is confirmed.'}catch{$('choice').textContent='Storage is unavailable. Your demo preference is displayed for this session.'}};
try{const saved=JSON.parse(localStorage.getItem('harvestlink-pitch-preference')||'null');if(saved&&Number.isFinite(saved.kg)&&saved.kg>=80&&saved.kg<=300&&saved.fx>=30&&saved.fx<=50&&saved.freight>=.3&&saved.freight<=1.2){$('kg').value=saved.kg;$('fx').value=saved.fx;$('freight').value=saved.freight;calculate();$('choice').textContent='Your saved demo preference was restored on this device.'}}catch{}
const modes={online:['WhatsApp / SMS adapter','Intent + trusted tools','Shared account','Markets + handover','Messages become reviewed records and useful next steps. A verified linked account connects messaging with the CRM. WhatsApp is the demonstrated channel; other delivery adapters are configurable.'],offline:['Cached phone companion','Compact local intent AI','IndexedDB + outbox','Reconnect + sync review','Download the app and model while connected. Then interpret intent, prepare harvest records, review saved comparisons and save choices locally. Durable operations wait for connectivity; reconnection uses revisions and conflict review.']};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const a=modes[b.dataset.mode];['channel','intelligence','storage','outcome','mode-copy'].forEach((id,i)=>$(id).textContent=a[i])});document.querySelector('[data-mode="online"]').click();
$('present').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen()}else{await document.documentElement.requestFullscreen()}}catch{window.location.hash='opportunity'}};
const chapters=[...document.querySelectorAll('main>.chapter')];document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT','BUTTON','SUMMARY'].includes(e.target.tagName))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();let index=chapters.reduce((best,s,i)=>Math.abs(s.getBoundingClientRect().top-100)<Math.abs(chapters[best].getBoundingClientRect().top-100)?i:best,0);index=Math.max(0,Math.min(chapters.length-1,index+(e.key==='ArrowRight'?1:-1)));chapters[index].scrollIntoView()}});
new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('selected',a.hash===`#${e.target.id}`))}})},{rootMargin:'-15% 0px -60% 0px'}).observe($('opportunity'));
['why','product'].forEach(id=>new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('selected',a.hash===`#${id}`))}),{rootMargin:'-15% 0px -60% 0px'}).observe($(id)));
